<script setup>
import {ref} from 'vue';import a from '../data/model-artifacts.json'
const view=ref('candidates');const base=import.meta.env.BASE_URL
</script>
<template><div class="stack"><div class="tabs"><button :aria-pressed="view==='candidates'" @click.stop="view='candidates'">Rendered candidates</button><button :aria-pressed="view==='directions'" @click.stop="view='directions'">Direction / magnitude grid</button></div><div v-if="view==='candidates'" class="candidate-images"><figure class="photo-frame"><img class="photo" :src="base+a.query.original" alt="Original FiveK example"/><figcaption>Original · {{a.query.id}}</figcaption></figure><figure v-for="i in 5" :key="i" class="photo-frame"><img v-if="a.candidates[i-1]" class="photo" :src="base+a.candidates[i-1].image" :alt="`Exported candidate ${i}`"/><div v-else class="missing"><strong>Candidate {{i}}</strong><span class="small">No model export</span></div><figcaption>{{a.candidates[i-1]?`Rank ${i} · exported output`:'No image or metric inferred'}}</figcaption></figure></div><div v-else-if="a.directionGrid.length" class="direction-images"><figure v-for="entry in a.directionGrid" :key="`${entry.direction}-${entry.scale}`" class="photo-frame"><img class="photo" :src="base+entry.image" :alt="`Direction ${entry.direction}, magnitude multiplier ${entry.scale}`"/><figcaption>{{entry.direction}} · {{entry.scale}} × magnitude</figcaption></figure></div><div v-else class="missing grow"><strong>Learned direction / magnitude images are unavailable.</strong><p class="small">The component accepts exported images with direction labels and magnitude multipliers.</p><p class="small">Expert target photographs are never substituted for model outputs.</p></div><p class="note">Populate data/model-artifacts.json with checkpoint-linked outputs to use these slots. Validation checks local paths and required run identity. The supplied evidence currently contains real input/target photographs, but no final flow5 output images.</p></div></template>
<style scoped>.candidate-images{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.candidate-images .photo,.candidate-images .missing{height:151px;min-height:151px;object-fit:contain}.direction-images{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.direction-images .photo{height:120px}</style>
